// Arıza özetini kurar. Sır TAŞIMAZ: yalnız workflow adı, çalıştırma
// kimliği, düğüm adı ve hata mesajı basılır; `stack` ve ham `data`
// DIŞARIDA bırakılır — yığın izi bağlantı dizesi ve başlık taşıyabilir.
const hata = $('Hata Tetikleyici').first().json || {};
const is = hata.workflow || {};
const kosum = hata.execution || {};
const ayrinti = kosum.error || {};
const satirlar = [
  '🔴 n8n arızası',
  `workflow: ${is.name || is.id || 'bilinmiyor'}`,
  `calistirma: ${kosum.id || 'bilinmiyor'}`,
  `dugum: ${ayrinti.node && ayrinti.node.name ? ayrinti.node.name : '-'}`,
  `hata: ${ayrinti.message || 'mesaj yok'}`,
];
if (kosum.url) { satirlar.push(`kayit: ${kosum.url}`); }
return [{ json: { message: satirlar.join('\n') } }];
